from __future__ import annotations
from pathlib import Path
import json
from .presets import PRESETS, MODE_DEFAULTS


def build_questionnaire(out: str | Path, image_prefix: str = "presets") -> Path:
    presets = json.dumps(PRESETS, ensure_ascii=False)
    defaults = json.dumps(MODE_DEFAULTS, ensure_ascii=False)
    cards = ''.join(f'''<label class="card"><input type="radio" name="palette" value="{k}" {'checked' if k=='portfolio-premium' else ''}><img src="{image_prefix}/{k}.svg" alt="{v['label']}"><b>{v['label']}</b><span>{k}</span></label>''' for k,v in PRESETS.items())
    html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Archi Studio · 意向问卷</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f5f7fb;color:#101828;font-family:Inter,"Noto Sans CJK SC","Microsoft YaHei",sans-serif}}main{{max-width:1180px;margin:auto;padding:32px}}h1{{margin:0 0 6px}}p{{color:#667085}}.row{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}}.card{{background:white;border:2px solid #e2e8f0;border-radius:16px;padding:10px;cursor:pointer}}.card:has(input:checked){{border-color:#2f6bff;box-shadow:0 0 0 3px #eef4ff}}.card input{{display:none}}.card img{{width:100%;border-radius:10px;display:block;margin-bottom:8px}}.card b,.card span{{display:block}}.card span{{font-size:12px;color:#667085}}.form{{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:22px 0}}select{{width:100%;height:42px;border:1px solid #d8e1ec;border-radius:10px;padding:0 10px;background:#fff}}button{{border:0;background:#2f6bff;color:white;padding:11px 16px;border-radius:10px;font-weight:700;cursor:pointer}}pre{{background:#fff;border:1px solid #d8e1ec;border-radius:12px;padding:14px;overflow:auto}}@media(max-width:850px){{.row,.form{{grid-template-columns:1fr 1fr}}}}@media(max-width:520px){{.row,.form{{grid-template-columns:1fr}}}}</style></head><body><main><h1>Archi Studio · 项目双架构图意向问卷</h1><p>选择用途与视觉方向。配置可直接交给 <code>archi-studio build --config</code> 或 Agent 使用。</p><h2>① 选择效果风格</h2><div class="row">{cards}</div><h2>② 选择内容策略</h2><div class="form"><label>用途<select id="mode"><option value="resume">简历 / 面试</option><option value="portfolio" selected>作品集 / Portfolio</option><option value="academic">答辩 / 学术</option><option value="business">商务汇报</option></select></label><label>内容密度<select id="density"><option value="concise">精简</option><option value="balanced" selected>平衡</option><option value="detailed">详细</option></select></label><label>语言<select id="language"><option value="zh+en" selected>中文 + 必要英文/缩写</option><option value="bilingual">中英均衡</option><option value="zh">全中文</option><option value="en">全英文</option></select></label><label>重点<select id="emphasis"><option value="product_evolution">产品演进</option><option value="balanced" selected>均衡</option><option value="technical">技术结构</option></select></label></div><button id="download">导出 diagram.config.json</button><pre id="preview"></pre></main><script>const PRESETS={presets},MODE_DEFAULTS={defaults};function cfg(){{const p=document.querySelector('input[name=palette]:checked').value;return{{mode:mode.value,density:density.value,palette:p,language:language.value,emphasis:emphasis.value,interactive_editor:true,typography_scale:1,spacing_scale:1,width_mm:94,height_mm:188}}}}function sync(){{preview.textContent=JSON.stringify(cfg(),null,2)}}document.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',sync));mode.addEventListener('change',()=>{{const d=MODE_DEFAULTS[mode.value]||{{}};if(d.palette)document.querySelector(`input[value="${{d.palette}}"]`).checked=true;if(d.density)density.value=d.density;if(d.emphasis)emphasis.value=d.emphasis;sync()}});download.onclick=()=>{{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(cfg(),null,2)],{{type:'application/json'}}));a.download='diagram.config.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}};sync();</script></body></html>'''
    p=Path(out); p.write_text(html,encoding='utf-8'); return p
